import { client } from "@trigger.dev/sdk/v3";
import { webhookHandler } from "./src/trigger/webhook";

// Initialize the Trigger.dev client
client.init();

async function main() {
  const idempotencyKey = "test-payment-12345";
  const amount = 99.99;

  console.log("Triggering webhook task twice with the same idempotency key...");
  console.log(`Idempotency Key: ${idempotencyKey}`);
  console.log(`Amount: ${amount}`);
  console.log("");

  // Trigger the task twice with the same idempotency key
  console.log("Triggering task execution 1...");
  const run1 = await webhookHandler.trigger(
    { idempotencyKey, amount },
    { idempotencyKey }
  );
  console.log(`Run 1 started with ID: ${run1.id}`);

  console.log("");

  console.log("Triggering task execution 2...");
  const run2 = await webhookHandler.trigger(
    { idempotencyKey, amount },
    { idempotencyKey }
  );
  console.log(`Run 2 started with ID: ${run2.id}`);

  console.log("");
  console.log("Summary:");
  console.log(`Run ID 1: ${run1.id}, Run ID 2: ${run2.id}`);

  // Wait for runs to complete
  console.log("");
  console.log("Waiting for runs to complete...");

  const result1 = await run1.waitForCompletion();
  console.log(`Run 1 completed with status: ${result1.status}`);

  const result2 = await run2.waitForCompletion();
  console.log(`Run 2 completed with status: ${result2.status}`);

  console.log("");
  console.log("Results:");
  console.log("Run 1:", JSON.stringify(result1, null, 2));
  console.log("Run 2:", JSON.stringify(result2, null, 2));

  console.log("");
  console.log("Idempotency verification:");
  if (result1.output && result2.output) {
    console.log("Run 1 output:", result1.output);
    console.log("Run 2 output:", result2.output);

    // Check if both runs returned the same result
    if (JSON.stringify(result1.output) === JSON.stringify(result2.output)) {
      console.log("✓ Both runs returned the same result (idempotency working!)");
    } else {
      console.log("✗ Runs returned different results");
    }
  }
}

main().catch(console.error);

